var calc_output = [];

var sex = parseFloat(sex);
var age = parseFloat(age);
var weight = parseFloat(weight);
var hf = parseFloat(hf);
var vd = parseFloat(vd);
var stroke = parseFloat(stroke);
var bleeding = parseFloat(bleeding);
var cod = parseFloat(cod);
var diabetes = parseFloat(diabetes);
var ckd = parseFloat(ckd);
var dementia = parseFloat(dementia);
var smoker = parseFloat(smoker);
var oac = parseFloat(oac);
var ap = parseFloat(ap);
var ethnicity = parseFloat(ethnicity);
var pulse = parseFloat(pulse);
var dbp = parseFloat(dbp);

var noac;
var vka;
if (oac == 0) {
    noac = 0;
    vka = 0;
} else if (oac == 1) {
    noac = 1;
    vka = 0;
} else if (oac == 2) {
    noac = 0;
    vka = 1;
}

var hisp;
var asian;
var black;
if (ethnicity == 0) {
    hisp = 0;
    asian = 0;
    black = 0;
} else if (ethnicity == 1) {
    hisp = 1;
    asian = 0;
    black = 0;
} else if (ethnicity == 2) {
    hisp = 0;
    asian = 1;
    black = 0;
} else if (ethnicity == 3) {
    hisp = 0;
    asian = 0;
    black = 1;
}

var age_l_65;
var age_g_65;
if (age <= 65) {
    age_l_65 = 1;
    age_g_65 = 0;
} else {
    age_l_65 = 0;
    age_g_65 = 1;
}

var weight_l_75;
if (weight <= 75) {
    weight_l_75 = 1;
} else {
    weight_l_75 = 0;
}

var pulse_l_120;
if (pulse <= 120) {
    pulse_l_120 = 1;
} else {
    pulse_l_120 = 0;
}

var dbp_l_80;
var dbp_g_80;
if (dbp <= 80) {
    dbp_l_80 = 1;
    dbp_g_80 = 0;
} else {
    dbp_l_80 = 0;
    dbp_g_80 = 1;
}

var all_x = -0.306202287*sex + 0.693789082*hf + 0.306120964*vd + 0.26585298*stroke + 0.385407386*bleeding + 0.280133213*diabetes + 0.377903886*ckd + 0.489453313*dementia + 0.345481149*smoker - 0.414591263*noac - 0.18593561*vka + 0.157023564*hisp - 0.609609055*asian + 0.375675102*black + 0.031050027*(age - 65)*age_l_65 + 0.064594824*(age - 65)*age_g_65 - 0.021535182*(weight - 75)*weight_l_75 + 0.007678035*(pulse - 120)*pulse_l_120 - 0.019304333*(dbp - 80)*dbp_l_80;
var stroke_x = 0.233182644*hf + 0.197919709*vd + 0.800863063*stroke + 0.29883967*bleeding + 0.211995445*diabetes + 0.349516938*ckd + 0.513221391*dementia + 0.478831506*smoker - 0.572199357*noac - 0.352373263*vka + 0.039138147*(age - 65) + 0.01590016*(dbp - 80)*dbp_g_80;
